@spec library_spec  src=tests/specs/library_spec.lua  loc=265  cases=17
@exercises configManager (h.cm)
@surface   cm:getAt, cm:set, cm:defaultFor
@harness   mk

# Intent
  Pin-tests for library.lua: the shared project/library tier module. The
  factory catalogue (cm:defaultFor) is a seed source, not a resolution tier --
  seedIfEmpty stocks an empty library, reloadPlan/importFactory re-import it.
  Instantiated directly over a harness cm (no in-module production caller).
  One case per verb, plus the synthetic floor's exemptions.

# Helpers
  @fn mkLib(h)  @ 10-15

# Cases
  @case 'names splits project and library, dropping the synthetic floor'  [harness]  @ 19-30
  @case 'get resolves project over library'  [harness]  @ 33-43
  @case 'localize copies a resolvable entry to project and is idempotent'  [harness]  @ 46-57
  @case 'localize skips synthetic names'  [harness]  @ 60-66
  @case 'forkToProject localizes then returns the project copy'  [harness]  @ 69-76
  @case 'save authors into project, leaving a same-named library copy standing'  [harness]  @ 79-90
  @case 'publish copies the project entry to the library tier'  [harness]  @ 94-102
  @case 'publish no-ops without a project copy'  [harness]  @ 105-111
  @case 'publishOverwrites is true only for a divergent library copy'  [harness]  @ 114-131
  @case 'revert overwrites the project copy from its library source'  [harness]  @ 134-144
  @case 'revert no-ops without a library source'  [harness]  @ 147-156
  @case 'modified: false pristine, true divergent, false for a source-less entry'  [harness]  @ 159-176
  @case 'tidy drops pristine unreferenced entries, keeps inUse and divergent ones'  [harness]  @ 179-202
  @case 'delete removes from the named tier and refuses synthetic names'  [harness]  @ 205-218
  @case 'seedIfEmpty stocks an empty library from the factory catalogue, once'  [harness]  @ 221-235
  @case 'reloadPlan splits absent factory names from divergent library copies'  [harness]  @ 238-251
  @case 'importFactory copies one entry into the library, refusing synthetic'  [harness]  @ 254-263

# Uses (outbound edges)
  @use call cm:getAt  @ 50,52,55,65,75,86,87,89,101,110,142,154,197,213,215,217,225,227,232,259,262
